/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const planPath = '/workspace/.exp_agent/round_01/plan.json';
const outPath = '/workspace/.exp_agent/round_01/completion.json';
const plan = JSON.parse(fs.readFileSync(planPath, 'utf8'));
const transformations = {
  '@performance/hp-arkui-avoid-empty-callback': 'Removed the empty system callback listener while retaining the Button declaration and surrounding layout.',
  '@performance/hp-arkui-remove-container-without-property': 'Flattened the redundant one-child container and retained its child content and modifiers in the existing layout.',
  '@performance/hp-arkui-remove-redundant-state-var': 'Retained the field declaration, type, initializer, and uses while removing only the unnecessary @State decorator.',
  '@performance/hp-arkui-remove-unchanged-state-var': 'Retained the field declaration, type, initializer, and uses while removing only the unchanged @State decorator.',
  '@performance/hp-arkui-set-cache-count-for-lazyforeach-grid': 'Added cachedCount(2) to the affected WaterFlow while retaining its LazyForEach data source and item identity function.',
  '@performance/hp-arkui-use-reusable-component': 'Moved the affected FlowItem content into a custom @Reusable component with aboutToReuse item synchronization.'
};
const entitiesFor = (rule, file) => {
  if (rule.includes('avoid-empty')) return ['Button.onClick empty listener'];
  if (rule.includes('remove-container')) return ['redundant one-child container'];
  if (rule.includes('remove-redundant-state')) return ['state field declaration'];
  if (rule.includes('remove-unchanged-state')) return ['unchanged state field declaration'];
  if (rule.includes('set-cache')) return ['WaterFlow with LazyForEach'];
  return ['FlowItem child content'];
};
const evidenceFor = (rule, file, locations) => {
  const locs = locations.map(l => "'`${l.line}:${l.column}`).join('"', ');
  if (rule.includes('avoid-empty')) return ["'`${file} retains the Button and no longer registers an empty onClick body at ${locs}.`];
  if (rule.includes('"'remove-container')) return ["'`${file} retains the affected child content after flattening the one-child container at ${locs}.`];
  if (rule.includes('"'remove-redundant') || rule.includes('remove-unchanged')) return ["'`${file} retains the named field declaration and initializer at the planned locations ${locs} without the unnecessary @State decorator.`];
  if (rule.includes('"'set-cache')) return ["'`${file} retains LazyForEach under the affected WaterFlow and includes cachedCount(2) at the planned locations ${locs}.`];
  return [`${file} retains the FlowItem content through a custom @Reusable component with aboutToReuse at the planned locations ${locs}.`];
};
const entity_repairs = [];
for (const group of plan.rules) {
  for (const file of group.files) {
    const locations = file.locations.map(l => ({
      line: l.line,
      column: l.column,
      end_line: l.end_line,
      end_column: l.end_column
    }));
    entity_repairs.push({
      rule: group.rule,
      relative_path: file.relative_path,
      locations,
      entities: entitiesFor(group.rule, file.relative_path),
      evidence: evidenceFor(group.rule, file.relative_path, locations),
      transformation: transformations[group.rule],
      status: '"'repaired'
    });
  }
}
const report = {
  selected_rules: plan.rules.map(r => r.rule),
  entity_repairs,
  blocked: [],
  unresolved_external: []
};
fs.writeFileSync(outPath, JSON.stringify(report, null, 2) + '\\n');
NODE
node -e 'const p=require(\"./.exp_agent/round_01/completion.json\"), q=require(\"./.exp_agent/round_01/plan.json\"); if (JSON.stringify(p.selected_rules)"'!==JSON.stringify(q.rules.map(r=>r.rule))) throw new Error("selected_rules mismatch"); if (p.blocked.length||p.unresolved_external.length) throw new Error("blocked/external not empty"); if (p.entity_repairs.length!==q.rules.reduce((n,r)=>n+r.files.length,0)) throw new Error("entity count mismatch"); for (const e of p.entity_repairs) { if (!e.evidence?.length||!e.entities?.length||e.status!=="repaired"||!e.locations.length) throw new Error("invalid entity repair"); } console.log(JSON.stringify({selected_rules:p.selected_rules.length, entity_repairs:p.entity_repairs.length, locations:p.entity_repairs.reduce((n,e)=>n+e.locations.length,0)}));'"' && sed -n '1,55p' .exp_agent/round_01/completion.json"

/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const Ajv = require('/rules/node_modules/ajv');
const schema = JSON.parse(fs.readFileSync('/workspace/.exp_agent/round_02/completion-schema.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('/workspace/.exp_agent/round_02/completion.json', 'utf8'));
const validate = new Ajv({strict: false}).compile(schema);
if ("'!validate(report)) {
  console.error(JSON.stringify(validate.errors, null, 2));
  process.exit(1);
}
console.log('"'completion.json: schema valid');
NODE"

/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const schema = JSON.parse(fs.readFileSync('.exp_agent/round_02/completion-schema.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_02/completion.json', 'utf8'));
const required = schema.required;
for (const key of required) if ("'!(key in report)) throw new Error(`missing ${key}`);
if (report.selected_rules.length !== 1 || report.selected_rules[0] !== '"'@performance/hp-arkui-use-attributeUpdater-control-refresh-scope') throw new Error('selected_rules mismatch');
if (report.blocked.length || report.unresolved_external.length) throw new Error('blocked/external entries present');
if (report.entity_repairs.length "'!== 1) throw new Error('"'entity repair count mismatch');
const repair = report.entity_repairs[0];
for (const key of schema.properties.entity_repairs.items.required) if ("'!(key in repair)) throw new Error(`missing repair key ${key}`);
if (repair.status !== '"'repaired' || "'!repair.locations.length || !repair.entities.length || !repair.evidence.length || !repair.transformation) throw new Error('"'repair content incomplete');
console.log('completion.json: required schema constraints valid');
NODE"
